python3 - <<'PYEOF'
p='updates/engine-update.mjs'
s=open(p).read()

s=s.replace("""import { copyFileSync, mkdirSync, rmSync, renameSync, readFileSync, writeFileSync, existsSync } from 'node:fs';""",
"""import { copyFileSync, mkdirSync, rmSync, renameSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';""",1)
s=s.replace("""import { convergeWiring } from '../engine/scheduler/converge-wiring.mjs';""",
"""import { convergeWiring } from '../engine/scheduler/converge-wiring.mjs';
import { NEEDS_HUMAN_LABEL } from '../engine/scheduler/dispatch.mjs';""",1)

old = """// The terminal reasons this flow can end on. Every one of them is a refusal to
// write, never a partial update — and each is a sentence a human can act on,
// because the only thing waiting on the other side of a stop is a person.
export const NEEDS_HUMAN = 'needs-human';"""
new = '''// The terminal reasons this flow can end on. Every one of them is a refusal to
// write, never a partial update — and each is a sentence a human can act on,
// because the only thing waiting on the other side of a stop is a person. It is
// the scheduler's existing label, not a second spelling of the same idea: a repo
// with two "a human is needed" labels has neither.
export const NEEDS_HUMAN = NEEDS_HUMAN_LABEL;

// THE SELF-TEST GATE (DESIGN §2.5). The converged tree is asked "can Claudinite
// still run here?" before anything merges. It exists because of #555, where an
// engine change silently stopped every consumer pack from validating while the
// content checks stayed green — a content check cannot see its own machinery
// break, so a green sweep over a broken mount says nothing at all.
//
// Run from the MOUNT, never from the canon: the copy under test is the one the
// member will live with.
export function runSelfTest(root, run = defaultRun) {
  const st = join(root, SHARED_SUBDIR, 'engine', 'selftest.mjs');
  if (!existsSync(st)) return { ok: false, ran: false, output: 'no vendored selftest to gate on' };
  try { return { ok: true, ran: true, output: run(st, root) }; }
  catch (e) { return { ok: false, ran: true, output: `${e.stdout ?? ''}${e.stderr ?? ''}`.trim() || e.message }; }
}
const defaultRun = (st, root) => execFileSync(process.execPath, [st, '--root', root, '--strict'],
  { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], cwd: root });

// What happens to the update's PR, given the gate and the repo's own delivery
// preference. PURE — the whole policy in one place, so the shell that opens and
// merges the PR carries no judgment of its own.
//
//   green  → the repo's delivery setting decides (auto-merge, or leave for review)
//   red    → PR open, `needs-human`, stop. Every non-green terminal looks the same
//            (DESIGN §5); there is no "merge it anyway because the diff looked fine".
//
// `forceMergeOnRedCi` is the operator's signed judgment that a red gate is
// acceptable (owner decision 1). It is a PER-INVOCATION argument and is never read
// from the repo's declaration — a stored default would turn one operator's judgment
// about one release into a standing policy nobody remembers granting, which is the
// opposite of what an override is for. The outcome still records that it was used:
// an override that leaves no trace is indistinguishable from a gate that passed.
export function deliveryDecision({ selftestOk, delivery = 'auto-merge', forceMergeOnRedCi = false } = {}) {
  if (selftestOk) {
    return delivery === 'auto-merge'
      ? { action: 'merge', why: 'the converged tree passed its self-test' }
      : { action: 'keep', why: `the converged tree passed its self-test; delivery is "${delivery}", so the PR is the owner's to merge` };
  }
  if (forceMergeOnRedCi) {
    return { action: 'merge', forced: true, why: 'the converged tree FAILED its self-test, merged on the operator\\'s explicit force-merge-on-red-ci' };
  }
  return {
    action: 'needs-human',
    label: NEEDS_HUMAN,
    why: 'the converged tree FAILED its self-test — the machinery that runs the rules is not intact, so the PR stays open',
  };
}'''
assert s.count(old)==1
s=s.replace(old,new)

# wire the gate into the flow
old2 = """  return outcome('ok', `engine ${from ?? 'unstamped'} → ${ENGINE_VERSION}`, {
    from, to: ENGINE_VERSION, records, files: written.length, applied, wiring: wiring.changed,
  });"""
new2 = """  // 4. Gate on the converged tree, and say what happens to the PR. This flow does
  //    not open or merge it — that is the shell's, which carries a token; what it
  //    must never carry is the judgment, so the decision is made and reported here.
  const selftest = runSelfTest(targetRoot, selfTestRun);
  const decision = deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });

  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok',
    decision.why, {
      from, to: ENGINE_VERSION, records, files: written.length, applied, wiring: wiring.changed,
      selftest, decision,
    });"""
assert s.count(old2)==1
s=s.replace(old2,new2)

old3 = """export async function engineUpdate(targetRoot, { fullName, today, dryRun = false } = {}) {"""
new3 = """export async function engineUpdate(targetRoot, {
  fullName, today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun,
} = {}) {"""
assert s.count(old3)==1
s=s.replace(old3,new3)

old4 = """// Update `targetRoot` to this canon's engine version. `fullName` is the repo's
// owner/name, needed by the wiring converge. `today` pins the date fallback for a
// repo with no version stamp. `dryRun` runs every judgment and writes nothing —
// what the rehearsal wants, and what makes this testable against a real tree."""
new4 = """// Update `targetRoot` to this canon's engine version. `fullName` is the repo's
// owner/name, needed by the wiring converge. `today` pins the date fallback for a
// repo with no version stamp. `dryRun` runs every judgment and writes nothing —
// what the rehearsal wants, and what makes this testable against a real tree.
// `delivery` is the repo's own preference and `forceMergeOnRedCi` the operator's
// per-invocation override; both feed the decision this returns, never a merge it
// performs. `selfTestRun` is the gate's runner, injected so a test can drive both
// outcomes without a mount that is genuinely broken."""
assert s.count(old4)==1
s=s.replace(old4,new4)
open(p,'w').write(s)
PYEOF
node --test engine-tests/engine-update.test.mjs 2>&1 | grep -E "^(not ok|# (tests|pass|fail))|error:" | head -6

python3 - <<'PYEOF'
p='engine-tests/engine-update.test.mjs'
s=open(p).read()
s=s.replace("""import { engineUpdate, engineRecordsInGap, isEngineFile, NEEDS_HUMAN } from '../updates/engine-update.mjs';""",
"""import { engineUpdate, engineRecordsInGap, isEngineFile, NEEDS_HUMAN, deliveryDecision, runSelfTest } from '../updates/engine-update.mjs';""",1)
s += """
// --- the self-test gate and its override (#768 Phase 1) -----------------------

test('the gate decides by the self-test, and every non-green end looks the same', () => {
  assert.deepEqual(deliveryDecision({ selftestOk: true }).action, 'merge');
  // A repo that reviews its own PRs is not overridden by a green gate.
  assert.equal(deliveryDecision({ selftestOk: true, delivery: 'review' }).action, 'keep');

  const red = deliveryDecision({ selftestOk: false });
  assert.equal(red.action, 'needs-human');
  assert.equal(red.label, NEEDS_HUMAN);
  assert.match(red.why, /FAILED its self-test/);
  // Red is red whatever the repo's delivery preference says.
  assert.equal(deliveryDecision({ selftestOk: false, delivery: 'review' }).action, 'needs-human');
});

test('force-merge-on-red-ci is per-invocation, and leaves a trace when used', () => {
  const forced = deliveryDecision({ selftestOk: false, forceMergeOnRedCi: true });
  assert.equal(forced.action, 'merge');
  assert.equal(forced.forced, true, 'an override that leaves no trace is indistinguishable from a gate that passed');
  assert.match(forced.why, /force-merge-on-red-ci/);
  // Absent, the default is the gate — never the override.
  assert.equal(deliveryDecision({ selftestOk: false }).action, 'needs-human');
});

test('the override is never read from the repo — a stored default is not an override', async () => {
  // The whole point of "per-invocation, never a stored default": one operator's
  // judgment about one release must not become standing policy nobody remembers
  // granting. A declaration that asks for it is simply not consulted.
  const root = makeMember({ packs: ['basics'], forceMergeOnRedCi: true, claudinite: { forceMergeOnRedCi: true } });
  assert.deepEqual((await applyVendor(root)).errors, []);
  const r = await engineUpdate(root, { fullName: 'o/r', selfTestRun: () => { throw new Error('mount is broken'); } });
  assert.equal(r.status, NEEDS_HUMAN, 'the declaration asked to force a merge and was ignored');
  assert.equal(r.decision.action, 'needs-human');
  rmSync(root, { recursive: true, force: true });
});

test('a converged tree that fails its self-test ends at needs-human, with the update still applied', async () => {
  // The update itself is not rolled back: the mount is converged and stamped, and
  // what the gate decides is whether that lands on main — the PR stays open instead.
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const r = await engineUpdate(root, { fullName: 'o/r', selfTestRun: () => { const e = new Error('x'); e.stdout = 'selftest: 1 of 5 probes FAILED'; throw e; } });
  assert.equal(r.status, NEEDS_HUMAN);
  assert.equal(r.selftest.ok, false);
  assert.match(r.selftest.output, /probes FAILED/);
  assert.equal(stampOf(root).engineVersion, ENGINE_VERSION, 'the converge happened; the gate governs the merge');
  rmSync(root, { recursive: true, force: true });
});

test('the gate runs the MOUNT\\'s self-test, not the canon\\'s', async () => {
  const root = makeMember();
  assert.deepEqual((await applyVendor(root)).errors, []);
  const seen = [];
  await engineUpdate(root, { fullName: 'o/r', selfTestRun: (st, r) => { seen.push(st); return 'ok'; } });
  assert.ok(seen[0].startsWith(join(root, MOUNT)), `${seen[0]} is not inside the member's own mount`);
});

test('runSelfTest reports an absent gate as a failure, never as a pass', () => {
  // A mount with no selftest is not a green mount — it is one nothing can vouch for.
  const root = mkdtempSync(join(tmpdir(), 'claudinite-nomount-'));
  const r = runSelfTest(root);
  assert.equal(r.ok, false);
  assert.equal(r.ran, false);
  rmSync(root, { recursive: true, force: true });
});
"""
open(p,'w').write(s)
